// 1. Basic auto deduction (Value/Copy)
int x = 10;
const int& rx = x;

auto a1 = x;  // a1 is int
auto a2 = rx; // a2 is int (discards ref/const)

// 2. auto reference deduction
auto& ar1 = x;  // ar1 is int&
auto& ar2 = rx; // ar2 is const int&

// 3. auto with arrays/functions
int arr[3] = {1, 2, 3};
auto a_arr = arr; // a_arr is int*

// 4. decltype Basics (Exact Type)
double pi = 3.14;
const int count = 5;

decltype(pi) d1;        // d1 is double
decltype(count) d2 = 0; // d2 is const int

// 5. decltype of expression (Lvalue vs Rvalue)
int y = 5;
decltype(y) d3 = 1;     // d3 is int (variable)
decltype((y)) d4 = y;   // d4 is int& (lvalue expr)

// 6. decltype(auto) for perfect forwarding
template<typename T, typename U>
decltype(auto) multiply(T&& t, U&& u) {
    return std::forward<T>(t) * std::forward<U>(u);
}
